// libFuzzer harness: the pyodbc extension (all of src/*.cpp, sanitized and coverage-instrumented) is
// linked into this binary and registered as a builtin module of an embedded CPython. Each input is
// decoded by driver.py into pyodbc API calls against an in-memory SQLite database that is reached
// through unixODBC and the SQLite3 ODBC driver.
#include <Python.h>

#include <cstdint>
#include <cstdio>
#include <cstdlib>

extern "C" PyObject *PyInit_pyodbc(void);

// Generated by build.sh from driver.py.
extern "C" const char kDriverSource[];

static PyObject *g_run = nullptr;

static void Die(const char *what) {
  fprintf(stderr, "pyodbc_fuzz: %s\n", what);
  if (PyErr_Occurred()) PyErr_Print();
  abort();
}

extern "C" int LLVMFuzzerInitialize(int *, char ***) {
  // Python's allocator would hide extension heap bugs from ASan.
  setenv("PYTHONMALLOC", "malloc", 1);
  if (PyImport_AppendInittab("pyodbc", PyInit_pyodbc) < 0) Die("AppendInittab failed");

  PyConfig config;
  PyConfig_InitPythonConfig(&config);
  config.install_signal_handlers = 0;  // leave SIGSEGV/SIGABRT etc. to the sanitizers and libFuzzer
  config.write_bytecode = 0;
  config.site_import = 0;
  PyStatus status = Py_InitializeFromConfig(&config);
  PyConfig_Clear(&config);
  if (PyStatus_Exception(status)) Die("Py_InitializeFromConfig failed");

  PyObject *main_mod = PyImport_AddModule("__main__");
  if (!main_mod) Die("no __main__");
  PyObject *globals = PyModule_GetDict(main_mod);
  PyObject *res = PyRun_String(kDriverSource, Py_file_input, globals, globals);
  if (!res) Die("driver.py failed to load");
  Py_DECREF(res);
  g_run = PyDict_GetItemString(globals, "run");
  if (!g_run) Die("driver.py has no run()");
  Py_INCREF(g_run);
  return 0;
}

extern "C" int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
  if (size == 0) return -1;
  PyObject *arg = PyBytes_FromStringAndSize(reinterpret_cast<const char *>(data), size);
  if (!arg) Die("out of memory");
  PyObject *res = PyObject_CallFunctionObjArgs(g_run, arg, nullptr);
  Py_DECREF(arg);
  if (!res) Die("driver.run() raised");
  int rc = (res == Py_False) ? -1 : 0;
  Py_DECREF(res);
  return rc;
}
